      if (ledger.total.totals.requests == 0) return; // nothing was spent
      final dir = UsageLedgerWriter.usageDirFor(
        sessionsRoot: config.sessionRoot,
        sessionId: metadata.id,
      );
      await _persistFoldIfStale(dir, ledger);
